import assert from 'node:assert/strict';
import {readFile} from 'node:fs/promises';
async function nextFrame(reader,state) {
  for(;;){const at=state.text.indexOf('\n\n');if(at>=0){const frame=state.text.slice(0,at);state.text=state.text.slice(at+2);const lines=frame.split('\n');return {event:lines.find(line=>line.startsWith('event: '))?.slice(7),data:JSON.parse(lines.find(line=>line.startsWith('data: ')).slice(6))};}const chunk=await reader.read();if(chunk.done)throw new Error('Live stream ended before required update');state.text+=state.decoder.decode(chunk.value,{stream:true});}
}
export async function smoke(ctx) {
  const {ids,api,check}=ctx;
  await check('activity feed and explicit personal watch use canonical issue events',async()=>{
    const feed=await api('GET','/activity?'+new URLSearchParams({orgId:ids.orgId,projectId:ids.projectId,issueId:ids.issueId}));
    assert.ok(feed.items.some(event=>event.entityType==='issue'&&event.entityId===ids.issueId));
    const watch=(await api('POST','/subscriptions',{targetType:'project',targetId:ids.projectId})).subscription;
    assert.equal(watch.targetId,ids.projectId);assert.equal(watch.manual,true);
    assert.ok((await api('GET','/subscriptions?orgId='+ids.orgId)).items.some(item=>item.targetId===ids.issueId));
  });
  await check('owner mention produces unread inbox with reversible exact owned read state',async()=>{
    const inbox=await api('GET','/notifications?orgId='+ids.orgId);
    const notification=inbox.items.find(item=>item.activity.entityType==='comment'&&item.activity.entityId===ids.mentionCommentId);
    assert.ok(notification);assert.equal(notification.reason,'mention');assert.equal(notification.read,false);
    ids.browserNotificationId=notification.id;
    assert.equal((await api('PATCH','/notifications/'+notification.id,{read:true})).notification.read,true);
    assert.equal((await api('PATCH','/notifications/'+notification.id,{read:false})).notification.readAt,null);
    assert.equal((await ctx.request('PATCH','/notifications/'+notification.id,{read:true},{actor:'member'})).status,404);
  });
  await check('real authenticated SSE receives a member mutation and cleans up its stream',async()=>{
    const client=ctx.clients.owner,controller=new AbortController();const timer=setTimeout(()=>controller.abort(),4000);
    let reader;
    try{
      const headers=client.token?{authorization:'Bearer '+client.token}:{cookie:client.cookie};
      const response=await fetch(ctx.url+'/api/v1/events?orgId='+ids.orgId,{headers,signal:controller.signal});assert.equal(response.status,200);
      reader=response.body.getReader();const state={text:'',decoder:new TextDecoder()};assert.equal((await nextFrame(reader,state)).event,'ready');
      const comment=(await api('POST','/issues/'+ids.issueId+'/comments',{body:'Live acceptance @[Owner](user:'+ctx.clients.owner.user.id+')'},'member')).comment;
      ids.liveCommentId=comment.id;
      const event=await nextFrame(reader,state);assert.equal(event.event,'activity');assert.equal(event.data.entityId,comment.id);assert.equal(event.data.after.issueId,ids.issueId);
    }finally{clearTimeout(timer);controller.abort();if(reader)await reader.cancel().catch(()=>{});}
  });
  await check('digest batches private unread updates once and preserves browser notification state',async()=>{
    const created=await api('POST','/digests',{orgId:ids.orgId});assert.ok(created.count>=2);assert.equal((await api('POST','/digests',{orgId:ids.orgId})).count,0);
    const digests=await api('GET','/digests?orgId='+ids.orgId);assert.ok(digests.items.some(row=>row.id===created.digest.id));ids.digestId=created.digest.id;
    const live=(await api('GET','/notifications?orgId='+ids.orgId)).items.find(item=>item.activity.entityId===ids.liveCommentId);assert.ok(live);ids.inboxReadNotificationId=live.id;
    await api('POST','/notifications/mark',{ids:[live.id],read:true});
    const browser=(await api('GET','/notifications?orgId='+ids.orgId)).items.find(item=>item.id===ids.browserNotificationId);assert.equal(browser.read,false);
  });
  await check('actual feed inbox preferences and digest CLI families use scoped authentication',async()=>{
    assert.ok((await ctx.cli(['feed','list','--org',ids.orgId,'--issue',ids.issueId])).items.length);
    assert.ok((await ctx.cli(['inbox','list','--org',ids.orgId,'--state','unread'])).items.some(item=>item.id===ids.browserNotificationId));
    assert.equal((await ctx.cli(['inbox','preferences','--org',ids.orgId])).preferences.emailEnabled,true);
    assert.ok((await ctx.cli(['inbox','digests','--org',ids.orgId])).items.some(item=>item.id===ids.digestId));
  });
}
export async function restart(ctx) {
  await ctx.check('activity watches inbox read and unread state and digests survive restart',async()=>{
    const {ids,api}=ctx;const inbox=await api('GET','/notifications?orgId='+ids.orgId);
    assert.equal(inbox.items.find(item=>item.id===ids.browserNotificationId).read,false);
    assert.equal(inbox.items.find(item=>item.id===ids.inboxReadNotificationId).read,true);
    assert.ok((await api('GET','/activity?orgId='+ids.orgId+'&issueId='+ids.issueId)).items.some(event=>event.entityId===ids.liveCommentId));
    assert.ok((await api('GET','/subscriptions?orgId='+ids.orgId)).items.some(item=>item.targetType==='project'&&item.targetId===ids.projectId));
    assert.ok((await api('GET','/digests?orgId='+ids.orgId)).items.some(item=>item.id===ids.digestId));
  });
}
export async function remount(ctx) {
  await ctx.check('saved feed and inbox CLI read persisted state after fresh Workspace',async()=>{
    assert.ok((await ctx.cli(['feed','list','--org',ctx.ids.orgId,'--issue',ctx.ids.issueId])).items.length);
    assert.ok((await ctx.cli(['inbox','list','--org',ctx.ids.orgId])).items.some(item=>item.id===ctx.ids.browserNotificationId));
  });
}
export async function audit({checks}) {
  const docs=await readFile('docs/api-insight.md','utf8');for(const term of ['insight:read','insight:write','Last-Event-ID','shared','read/unread','credential','digest'])assert.ok(docs.includes(term),term);
  checks.push({name:'Activity notification watch digest and live credential/access/cleanup contracts documented; real HTTP SSE and token CLI suites cover behavior',ok:true});
}

import assert from 'node:assert/strict';
import {readFile} from 'node:fs/promises';
import path from 'node:path';
export async function smoke(ctx) {
  const {ids,api,check}=ctx;
  await check('dashboard counts throughput and burndown reuse visible canonical work',async()=>{
    const issues=await api('GET','/projects/'+ids.projectId+'/issues?limit=200');
    const report=await api('GET','/dashboard?orgId='+ids.orgId+'&projectId='+ids.projectId+'&sprintId='+ids.sprintId);
    assert.equal(report.totals.issues,issues.items.length);assert.ok(report.throughput.some(week=>week.issues>0));
    assert.deepEqual(report.burndown,await api('GET','/sprints/'+ids.sprintId+'/burndown'));
    assert.equal((await ctx.request('GET','/dashboard?orgId='+ids.orgId+'&projectId='+ids.privateProjectId,undefined,{actor:'guest'})).status,403);
  });
  await check('JSON CSV export validated preview and atomic remapped import preserve required content',async()=>{
    const document=await api('GET','/projects/'+ids.projectId+'/export');
    assert.equal(document.format,'crew.project');
    const csv=await ctx.request('GET','/projects/'+ids.projectId+'/export?format=csv');assert.equal(csv.status,200);assert.match(csv.data,/"number","title"/);assert.ok(csv.data.includes('Acceptance issue release'));
    const preview=await api('POST','/orgs/'+ids.orgId+'/import',{document,key:'ROUNDTRIP',preview:true});assert.equal(preview.preview.counts.issues,document.issues.length);
    const imported=await api('POST','/orgs/'+ids.orgId+'/import',{document,key:'ROUNDTRIP',name:'Acceptance imported project'});
    ids.importedProjectId=imported.project.id;ids.importedMappings=imported.mappings;ids.importedCounts=imported.counts;
    const again=await api('GET','/projects/'+imported.project.id+'/export');
    for(const key of ['issues','comments','labels','relations'])assert.equal(again[key].length,document[key].length,key);
    for(const source of document.issues){const item=again.issues.find(issue=>issue.id===imported.mappings.issues[source.id]);assert.ok(item);for(const key of ['title','description','priority','estimate','dueDate','createdAt','updatedAt'])assert.equal(item[key],source[key]);assert.equal(item.parentId,source.parentId?imported.mappings.issues[source.parentId]:null);}
    const invalid=structuredClone(document);invalid.issues[0].statusId='invalid-status';
    const bad=await ctx.request('POST','/orgs/'+ids.orgId+'/import',{document:invalid,key:'INVALID'});assert.equal(bad.status,422);
    assert.equal((await ctx.request('POST','/orgs/'+ids.orgId+'/import',{document,key:'DENIED'}, {actor:'guest'})).status,403);
  });
  await check('actual dashboard and streamed project export import CLI families roundtrip',async()=>{
    const file=path.join(ctx.dataDir,'insight-project.json');
    const exported=await ctx.cli(['export',ids.projectId,'--output',file]);assert.ok(exported.bytes>0);assert.equal(exported.sha256.length,64);
    const document=JSON.parse(await readFile(file,'utf8'));assert.ok(document.issues.some(issue=>issue.id===ids.issueId));
    const preview=await ctx.cli(['import','--org',ids.orgId,'--file',file,'--key','CLICOPY','--preview']);assert.equal(preview.preview.counts.issues,document.issues.length);
    const imported=await ctx.cli(['import','--org',ids.orgId,'--file',file,'--key','CLICOPY','--yes']);ids.cliImportedProjectId=imported.project.id;
    assert.equal(imported.counts.relations,document.relations.length);
    const report=await ctx.cli(['dashboard','--org',ids.orgId,'--project',ids.projectId]);assert.equal(report.totals.issues,document.issues.length);
  });
}
export async function restart(ctx) {
  await ctx.check('imported project closure and reporting persist across a new server process',async()=>{
    const document=await ctx.api('GET','/projects/'+ctx.ids.importedProjectId+'/export');
    for(const key of ['issues','comments','labels','relations'])assert.equal(document[key].length,ctx.ids.importedCounts[key]);
    const issue=document.issues.find(item=>item.id===ctx.ids.importedMappings.issues[ctx.ids.issueId]);assert.equal(issue.title,ctx.ids.issueExpected.title);
    const project=(await ctx.api('GET','/projects/'+ctx.ids.cliImportedProjectId)).project;assert.equal(project.key,'CLICOPY');
    assert.equal((await ctx.api('GET','/dashboard?orgId='+ctx.ids.orgId+'&projectId='+ctx.ids.importedProjectId)).totals.issues,document.issues.length);
  });
}
export async function remount(ctx) {
  await ctx.check('saved dashboard CLI reads imported persisted project after fresh mount',async()=>{
    const report=await ctx.cli(['dashboard','--org',ctx.ids.orgId,'--project',ctx.ids.importedProjectId]);assert.equal(report.totals.issues,ctx.ids.importedCounts.issues);
  });
}
export async function audit({checks}) {
  const docs=await readFile('docs/api-insight.md','utf8');for(const term of ['export:read','import:write','externalIssueMap','getBurndown','atomic','CSV','SVG','next_issue_number'])assert.ok(docs.includes(term),term);
  checks.push({name:'Dashboard canonical ledger and streamed validated remapped project transfer contracts documented; HTTP rollback/roundtrip and actual CLI suites qualify behavior',ok:true});
}

